// Mesas de ayuda por columna de Trello. Tango va por EMAIL; Ayres va por WHATSAPP.
// Cuando Pablo pase el chat de Ayres (JID), cargarlo en AYRES_CHAT_WA y la columna se activa.
const AYRES_CHAT_WA = '120363410195428550@g.us'; // grupo "P 607 00 El Desembarco - ADM Sistemas" (el definitivo)
const MESAS = {
  '6a689b2b078eec227dc02ea5': { mesa: 'Mesa de Ayuda Tango', via: 'email', destino: 'mesadeayuda@seincomp.com.ar' },
  '6a689bcabc131c785ef97206': { mesa: 'Mesa de Ayuda Ayres IT', via: 'wa', destino: AYRES_CHAT_WA }
};
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.sentMesa)) sd.sentMesa = [];
const out = [];
for (const item of $input.all()) {
  const c = item.json;
  if (!c || !c.id) continue;
  if (sd.sentMesa.includes(c.id)) continue; // ya enviado: la card queda en la columna sin reenviar
  const cfg = MESAS[c.idList] || { mesa: 'Mesa de ayuda', via: 'email', destino: '' };
  if (!cfg.destino) continue; // mesa sin canal configurado: la card queda sin enviar
  const atts = (c.attachments || []).filter(a => a.url && a.isUpload !== false);
  const nombre = (c.name || '').replace(/^[^0-9A-Za-z\[Ã€-Å¿]+\s*/, '');
  const ref = (((c.shortUrl || '').split('/c/')[1]) || c.id);
  const detalle = (c.desc || '').split('\n---')[0].trim();
  const cuerpo = ['Estimados,', '', 'Solicitamos asistencia por el siguiente requerimiento:', '', detalle, '', 'Gracias,', 'Sistemas El Desembarco'].join('\n');
  const waMessage = `ðŸ†• *Requerimiento El Desembarco* (Ref ${ref})\n\n${nombre}\n\n${detalle}\n\n_Por favor responder citando este mensaje._`;
  out.push({ json: {
    cardId: c.id, cardName: c.name, shortUrl: c.shortUrl,
    mesa: cfg.mesa, via: cfg.via, destino: cfg.destino,
    asunto: ('[El Desembarco] ' + nombre).slice(0, 100) + ' (Ref ' + ref + ')',
    cuerpo, waMessage,
    attUrl: atts.length ? atts[0].url : '',
    attList: atts.map(a => ({ url: a.url, name: a.fileName || a.name || 'adjunto', mime: a.mimeType || 'application/octet-stream' }))
  } });
}
return out;

// Notifica una sola vez por card resuelta: al chat de origen y, si el origen es un
// grupo, TAMBIEN al solicitante por privado.
// Si la card tiene un comentario con la clave nueva (ej: 'clave: Abc123'), la clave
// va SOLO en el mensaje privado al solicitante, nunca al grupo.
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.notified)) sd.notified = [];
const out = [];
for (const item of $input.all()) {
  const c = item.json;
  if (!c || !c.id) continue;
  if (sd.notified.includes(c.id)) continue;
  sd.notified.push(c.id);
  if (sd.notified.length > 500) sd.notified = sd.notified.slice(-400);
  const mChat = (c.desc || '').match(/\*\*Chat:\*\* ([^\s\n]+)/);
  if (!mChat) continue; // card creada a mano, sin origen WhatsApp
  const mSol = (c.desc || '').match(/\*\*Solicitante:\*\* ([^\s\n]+)/);

  // Buscar clave en comentarios (del mas nuevo al mas viejo), ignorando los comentarios automaticos del sistema
  let clave = '';
  for (const a of (c.actions || [])) {
    const t = (a.data && a.data.text) || '';
    if (/^[âœ…âš \ud83c\ud83d\ud83e\ud83fâœ‰â�—ðŸ””]/u.test(t)) continue;
    const m = t.match(/(?:clave|contrase[Ã±n]a|password|pass)[^\S\n]*(?:provisoria|temporal|nueva)?[^\S\n]*[:=][^\S\n]*(\S+)/i);
    if (m) { clave = m[1]; break; }
  }

  const msgBase = `âœ… Resuelto: ${c.name}\n${c.shortUrl}${mSol ? '\n(solicitado por ' + mSol[1] + ')' : ''}`;
  const msgConClave = clave ? msgBase + `\n\nðŸ”‘ Tu nueva clave provisoria es: ${clave}\nCambiala al ingresar.` : msgBase;
  const esGrupo = mChat[1].endsWith('@g.us');

  // Aviso al chat de origen: si es grupo, SIN clave
  out.push({ json: { cardId: c.id, recipient: mChat[1], message: esGrupo ? (clave ? msgBase + '\nðŸ”‘ La clave nueva te llega por mensaje privado.' : msgBase) : msgConClave } });
  // Aviso privado al solicitante (con clave si la hay)
  if (mSol && esGrupo) {
    const solJid = mSol[1].includes('@') ? mSol[1] : mSol[1] + '@s.whatsapp.net';
    if (solJid !== mChat[1]) out.push({ json: { cardId: c.id, recipient: solJid, message: msgConClave } });
  }
}
return out;

// Descarga TODOS los adjuntos de la card y los deja como binarios data0..dataN.
const OAUTH = 'OAuth oauth_consumer_key="0e2126dbfd8ca7c38318c2570e7bf532", oauth_token="ATTAac89aa35c1107c9ad5684977c731d18e375ec585f2e3e3bfbf84606bedaa3793FE3A3525"';
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const binary = {};
  const props = [];
  for (let i = 0; i < (j.attList || []).length; i++) {
    const a = j.attList[i];
    try {
      const resp = await this.helpers.httpRequest({ method: 'GET', url: a.url, headers: { Authorization: OAUTH }, encoding: 'arraybuffer', timeout: 60000 });
      binary['data' + i] = await this.helpers.prepareBinaryData(Buffer.from(resp), a.name, a.mime);
      props.push('data' + i);
    } catch (e) { /* adjunto que no baja no frena el email */ }
  }
  out.push({ json: { ...j, binaryProps: props.join(',') }, binary });
}
return out;

